using System.ComponentModel.DataAnnotations;
namespace Lesson09_Lab.Areas.Admin.Models;
public class Product { public int Id {get;set;} [Required, StringLength(100)] public string Name {get;set;} = ""; [Range(0, 1000000000)] public decimal Price {get;set;} [Range(0, 1000000000)] public decimal SalePrice {get;set;} public int Status {get;set;} = 1; [Required] public int CategoryId {get;set;} public DateTime CreatedDate {get;set;} = DateTime.Today; [StringLength(100)] public string? Image {get;set;} [StringLength(350)] public string? Description {get;set;} public Category? Category {get;set;} }